window.products.push({"id":955232,"name":"ChillGel The Original Cool Slumber Mattress Pad, Medium","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71Qdrxk2seL._AC_SL1500_.jpg","description":"The Original Cool Slumber Mattress Pad's ChillGel technology actively regulates the body's temperature by absorbing heat away from it so that you can sleep comfortably cool all night long. ChillGel creates a thermal break between you and the mattress to absorb body heat into The Original Cool Slumber Mattress Pad rather than storing it in the bedding and transferring back during sleep. The result is a comfortable sleeping temperature all night long, without the need for plug-in devices, water or refrigeration of any kind. Pad temperature will vary depending on your body temperature and pressure on the pad. Care: Do not machine wash or dry; spot wipe if needed. Excessive heat exposure will prevent pad from feeling cool.","images":["https://m.media-amazon.com/images/I/71Qdrxk2seL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"ChillGel","source_asin":"B00D792Z7C","category_path":"Home & Kitchen"},"sku":"BM-955232","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00D792Z7C","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00D792Z7C","price_pending":true,"merchant_ready":false});
